result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/sparse-set.ts", "content": "/**
 * Sparse set: the classic entity-indexing structure used by ECS storages.
 *
 *  - `dense`  : tightly packed array of entities (cache-friendly iteration)
 *  - `sparse` : entity-id -> index into `dense` (O(1) lookup)
 *
 * add / remove / has are all O(1). Removal is a swap-with-last, which keeps
 * `dense` packed but unordered — exactly what we want for iteration speed.
 */
export class SparseSet {
  readonly dense: number[] = [];
  private readonly sparse: number[] = [];

  has(entity: number): boolean {
    const d = this.sparse[entity];
    return d !== undefined && d < this.dense.length && this.dense[d] === entity;
  }

  /** Index into `dense` if present, else -1. */
  indexOf(entity: number): number {
    const d = this.sparse[entity];
    return d !== undefined && d < this.dense.length && this.dense[d] === entity ? d : -1;
  }

  add(entity: number): boolean {
    if (this.has(entity)) return false;
    this.sparse[entity] = this.dense.length;
    this.dense.push(entity);
    return true;
  }

  /** Swap-remove: moves the last dense entry into the hole. O(1). */
  remove(entity: number): boolean {
    const idx = this.indexOf(entity);
    if (idx === -1) return false;
    const last = this.dense.length - 1;
    const lastEntity = this.dense[last];
    this.dense[idx] = lastEntity;
    this.sparse[lastEntity] = idx;
    this.dense.pop();
    // Stale sparse entry for `entity` may remain; indexOf/has validate against
    // `dense`, so it is harmless and avoids an O(n) delete on arrays.
    return true;
  }

  get size(): number {
    return this.dense.length;
  }
}
"})
