export interface Position {
  x: number;
  y: number;
}

export interface Velocity {
  x: number;
  y: number;
}

/** A queued structural change, applied only after iteration completes. */
export interface DeferredRemoval {
  entity: number;
  component: string;
}

/**
 * Structure-of-arrays component store: `data[i]` is the payload for
 * `set.dense[i]`, so iteration over the dense array walks contiguous,
 * cache-friendly memory. Swap-remove keeps data and index map in sync.
 */
export class ComponentStore<T> {
  readonly set = new SparseSet();
  readonly data: T[] = [];

  add(entity: number, value: T): void {
    this.set.add(entity);
    this.data[this.set.dense.length - 1] = value;
  }

  remove(entity: number): boolean {
    const idx = this.set.indexOf(entity);
    if (idx === -1) return false;
    const last = this.set.dense.length - 1;
    this.data[idx] = this.data[last];
    this.data.pop();
    this.set.remove(entity);
    return true;
  }

  get(entity: number): T | undefined {
    const i = this.set.indexOf(entity);
    return i === -1 ? undefined : this.data[i];
  }

  has(entity: number): boolean {
    return this.set.has(entity);
  }
}

export class World {
  private nextEntity = 0;
  private readonly stores = new Map<string, ComponentStore<unknown>>();

  spawn(): number {
    return this.nextEntity++;
  }

  store<T>(name: string): ComponentStore<T> | undefined {
    return this.stores.get(name) as ComponentStore<T> | undefined;
  }

  add<T>(entity: number, component: string, value: T): void {
    let s = this.stores.get(component) as ComponentStore<T> | undefined;
    if (!s) {
      s = new ComponentStore<T>();
      this.stores.set(component, s as ComponentStore<unknown>);
    }
    s.add(entity, value);
  }

  remove(entity: number, component: string): boolean {
    return this.stores.get(component)?.remove(entity) ?? false;
  }

  has(entity: number, component: string): boolean {
    return this.stores.get(component)?.has(entity) ?? false;
  }

  get<T>(entity: number, component: string): T | undefined {
    return this.store<T>(component)?.get(entity);
  }

  count(component: string): number {
    return this.stores.get(component)?.set.size ?? 0;
  }

  /**
   * Two-component iteration. Walks the smaller dense array and probes the
   * larger set — the classic archetype-query. Backwards iteration means a
   * callback may even remove the current entity safely (swap-remove re-fills
   * slot i from the already-visited tail).
   */
  each2<A, B>(
    a: string,
    b: string,
    cb: (entity: number, compA: A, compB: B) => void,
  ): void {
    const sa = this.store<A>(a);
    const sb = this.store<B>(b);
    if (!sa || !sb || sa.set.size === 0) return;

    if (sa.set.dense.length <= sb.set.dense.length) {
      const dense = sa.set.dense;
      const dataA = sa.data;
      for (let i = dense.length - 1; i >= 0; i--) {
        const e = dense[i];
        const j = sb.set.indexOf(e);
        if (j === -1) continue;
        cb(e, dataA[i], sb.data[j]);
      }
    } else {
      const dense = sb.set.dense;
      const dataB = sb.data;
      for (let i = dense.length - 1; i >= 0; i--) {
        const e = dense[i];
        const j = sa.set.indexOf(e);
        if (j === -1) continue;
        cb(e, sa.data[j], dataB[i]);
      }
    }
  }

  /** Apply a deferred removal queue collected during iteration. */
  flush(queue: DeferredRemoval[]): void {
    for (let i = 0; i < queue.length; i++) {
      const r = queue[i];
      this.remove(r.entity, r.component);
    }
    queue.length = 0;
  }
}
